#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Image processing pipeline for Kubernetes pod - handles metadata propagation
 * between processing stages via a property chain mechanism.
 * Each image carries a metadata dictionary implemented as a linked property list.
 */

#define MAX_KEY_LEN 64
#define MAX_VAL_LEN 256
#define MAX_PROPERTIES 128
#define MAGIC_SENTINEL 0xDEADBEEF

typedef struct property_node {
    char key[MAX_KEY_LEN];
    char value[MAX_VAL_LEN];
    uint32_t flags;
    struct property_node *parent;  /* prototype chain - inherits from parent */
    struct property_node *next;
} property_node_t;

typedef struct {
    property_node_t *head;
    property_node_t *prototype;  /* shared base properties across pipeline stages */
    uint32_t sentinel;
    int count;
} property_chain_t;

typedef struct {
    uint32_t width;
    uint32_t height;
    uint8_t *pixels;
    property_chain_t *metadata;
    char stage_name[32];
} image_context_t;

static property_chain_t *global_prototype = NULL;

property_chain_t *chain_create(property_chain_t *proto) {
    property_chain_t *chain = calloc(1, sizeof(property_chain_t));
    if (!chain) return NULL;
    chain->prototype = proto;
    chain->sentinel = MAGIC_SENTINEL;
    chain->count = 0;
    chain->head = NULL;
    return chain;
}

/* Lookup traverses the prototype chain */
const char *chain_lookup(property_chain_t *chain, const char *key) {
    if (!chain || !key) return NULL;

    property_node_t *cur = chain->head;
    while (cur) {
        if (strncmp(cur->key, key, MAX_KEY_LEN) == 0)
            return cur->value;
        cur = cur->next;
    }

    /* Walk up prototype chain */
    if (chain->prototype)
        return chain_lookup(chain->prototype, key);

    return NULL;
}

/* Set property - prototype keys are rejected for security */
int chain_set(property_chain_t *chain, const char *key, const char *value) {
    if (!chain || !key || !value) return -1;
    if (chain->count >= MAX_PROPERTIES) return -1;
    if (strlen(key) >= MAX_KEY_LEN || strlen(value) >= MAX_VAL_LEN) return -1;

    /* Block any attempt to modify prototype chain from untrusted input */
    const char *proto_prefix = "__proto__.";
    size_t prefix_len = strlen(proto_prefix);

    if (strncmp(key, proto_prefix, prefix_len) == 0) {
        fprintf(stderr, "Security: blocked prototype modification attempt: %s\n", key);
        return -1;
    }

    /* Also block variations */
    if (strstr(key, "__proto__") != NULL || strstr(key, "prototype") != NULL) {
        fprintf(stderr, "Security: blocked suspicious key: %s\n", key);
        return -1;
    }

    /* Check if key exists, update in place */
    property_node_t *cur = chain->head;
    while (cur) {
        if (strncmp(cur->key, key, MAX_KEY_LEN) == 0) {
            strncpy(cur->value, value, MAX_VAL_LEN - 1);
            cur->value[MAX_VAL_LEN - 1] = '\0';
            return 0;
        }
        cur = cur->next;
    }

    /* Insert new node */
    property_node_t *node = calloc(1, sizeof(property_node_t));
    if (!node) return -1;
    strncpy(node->key, key, MAX_KEY_LEN - 1);
    strncpy(node->value, value, MAX_VAL_LEN - 1);
    node->next = chain->head;
    node->parent = NULL;
    chain->head = node;
    chain->count++;
    return 0;
}

/* Parse metadata from image EXIF-like header: "key1=val1;key2=val2;..." */
int parse_metadata_header(property_chain_t *chain, const char *header) {
    if (!chain || !header) return -1;

    char buf[1024];
    strncpy(buf, header, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';

    char *saveptr;
    char *token = strtok_r(buf, ";", &saveptr);

    while (token) {
        char *eq = strchr(token, '=');
        if (eq) {
            *eq = '\0';
            char *k = token;
            char *v = eq + 1;

            /* Trim leading spaces */
            while (*k == ' ') k++;
            while (*v == ' ') v++;

            if (strlen(k) > 0 && strlen(v) > 0) {
                chain_set(chain, k, v);
            }
        }
        token = strtok_r(NULL, ";", &saveptr);
    }
    return 0;
}

/* Security check: determines if image should be processed based on metadata */
int is_authorized(image_context_t *ctx) {
    const char *auth = chain_lookup(ctx->metadata, "authorized");
    if (auth && strcmp(auth, "true") == 0)
        return 1;
    return 0;
}

/* Pipeline stage: resize (simplified) */
int stage_resize(image_context_t *ctx) {
    if (!is_authorized(ctx)) {
        fprintf(stderr, "[%s] Unauthorized access denied\n", ctx->stage_name);
        return -1;
    }
    printf("[%s] Processing %ux%u image\n", ctx->stage_name, ctx->width, ctx->height);
    return 0;
}

/* Initialize the global pipeline prototype with safe defaults */
void pipeline_init(void) {
    global_prototype = chain_create(NULL);
    chain_set(global_prototype, "max_width", "4096");
    chain_set(global_prototype, "max_height", "4096");
    chain_set(global_prototype, "authorized", "false");
    chain_set(global_prototype, "output_format", "png");
}

/* Process an incoming image request from the k8s ingress */
int process_request(const char *metadata_header, uint32_t w, uint32_t h) {
    image_context_t ctx;
    memset(&ctx, 0, sizeof(ctx));
    ctx.width = w;
    ctx.height = h;
    strncpy(ctx.stage_name, "resize", sizeof(ctx.stage_name) - 1);

    /* Each request gets its own chain inheriting from global prototype */
    ctx.metadata = chain_create(global_prototype);
    if (!ctx.metadata) return -1;

    /* Parse untrusted metadata from request header */
    if (metadata_header) {
        parse_metadata_header(ctx.metadata, metadata_header);
    }

    int result = stage_resize(&ctx);

    /* Cleanup request-local chain (prototype persists) */
    property_node_t *cur = ctx.metadata->head;
    while (cur) {
        property_node_t *tmp = cur;
        cur = cur->next;
        free(tmp);
    }
    free(ctx.metadata);

    return result;
}

int main(int argc, char **argv) {
    pipeline_init();

    printf("=== Request 1: Normal unauthorized request ===\n");
    process_request("source=camera;format=jpeg", 1920, 1080);

    printf("\n=== Request 2: Attacker attempts prototype pollution ===\n");
    process_request("__proto__.authorized=true;source=malicious", 9999, 9999);

    printf("\n=== Request 3: Subsequent request remains unauthorized ===\n");
    process_request("source=camera;format=jpeg", 1920, 1080);

    return 0;
}
